import{_ as n,o as a,c as t,a2 as r}from"./chunks/framework.1C62pOns.js";const p=JSON.parse('{"title":"Screen guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/index.md","filePath":"en/interface/index.md","lastUpdated":1787856241000}'),s={name:"en/interface/index.md"};function o(i,e,l,d,h,g){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="screen-guide" tabindex="-1">Screen guide <a class="header-anchor" href="#screen-guide" aria-label="Permalink to &quot;Screen guide&quot;">​</a></h1><p>This guide does not list field by field. It explains <strong>what each screen is for, what decisions it asks of you and where people usually trip up</strong> — which is what you cannot work out by looking at the interface.</p><p>You can read the field labels on the screen itself, and they change from release to release; the reason behind each choice does not.</p><h2 id="reading-order" tabindex="-1">Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to &quot;Reading order&quot;">​</a></h2><p>If you are starting out, follow this order — each piece depends on the one before it:</p><ol><li><strong><a href="/pro-agent-hub-installer/en/interface/primeiros-passos">Getting started</a></strong> — signing in, finding your way around the menu, understanding the dashboard.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/provedores-modelos">Providers and models</a></strong> — where the intelligence comes from. Without this, nothing else works.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/conhecimento">Knowledge and data sources</a></strong> — what the platform knows beyond the model.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/agentes">Agents, teams and chat</a></strong> — who talks and who runs.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/workflows">Workflows</a></strong> — automation, visual or in code.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/planejadores">Planners</a></strong> — agents that work in a loop until a goal is met.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/mcp">MCP services</a></strong> — external tools and your own.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/apps">Apps</a></strong> — web screens built on the platform.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/integracoes">Integrations</a></strong> — WhatsApp and Microsoft Teams.</li><li><strong><a href="/pro-agent-hub-installer/en/interface/administracao">Administration</a></strong> — groups, users, settings, usage and copying data between environments.</li></ol><h2 id="what-every-screen-has-in-common" tabindex="-1">What every screen has in common <a class="header-anchor" href="#what-every-screen-has-in-common" aria-label="Permalink to &quot;What every screen has in common&quot;">​</a></h2><p><strong>List and detail.</strong> Almost every record type has a list screen, with search, and a detail screen, with tabs. The list has an <em>&quot;active only&quot;</em> filter — disabled records still exist, they just stay out of the way.</p><p><strong>Disabling is not deleting.</strong> A disabled record stops being used but keeps its history and its links. Deleting is permanent, and is usually refused while something still points at the record.</p><p><strong>Saving is explicit.</strong> Leaving a screen with unsaved changes raises a warning. Nothing is written until you confirm.</p><p><strong>What you see depends on your group.</strong> A non-master user only sees the agents, teams, workflows, planners, MCP services and Apps that one of their groups has released — and with the mode the group granted: <em>read</em> allows opening and running, <em>write</em> allows saving. See <a href="/pro-agent-hub-installer/en/interface/administracao">Administration</a>.</p>',11)])])}const u=n(s,[["render",o]]);export{p as __pageData,u as default};
